import{d as s,S as a,i as t,l as r}from"./chunks/framework.CY2TYXqZ.js";const m=JSON.parse('{"title":"精選節錄","description":"針對 Kestrel Press 教材選文編輯台的白箱滲透測試委託；投稿者在此編寫教材，課程編輯再將已選用的節錄組成講義。","frontmatter":{"title":"精選節錄","number":10,"layout":"challenge","difficulty":"medium","category":"web","backend":"flask","app":"app.py","packages":["flask"],"tools":["browser","network","repeater","code"],"source_visible":true,"source_files":["/templates/base.html","/templates/workbench.html","/templates/article.html","/templates/preview.html","/templates/course-pack.html","/templates/missing.html","/static/app.css"],"date":"2026-09-13T13:28:46.765Z","tags":["idor","access-control","ssti","template-injection","jinja2","flask"],"description":"針對 Kestrel Press 教材選文編輯台的白箱滲透測試委託；投稿者在此編寫教材，課程編輯再將已選用的節錄組成講義。","wasmModule":"/challenge/selected-excerpts/runtime.wasm","markdownBody":"\\n# 精選節錄\\n\\n**客戶：** 獨立教育出版社 Kestrel Press。\\n**委託：** 對投稿者編輯台，以及由已選用節錄組成的講義預覽進行白箱評估。\\n\\n## 測試範圍\\n\\n範圍內：此來源所提供的教材選文編輯台、它公開的每一個 HTTP 端點，以及隨應用程式掛載的原始碼檔案。\\n\\n你以一般投稿者 **Leah Navarro** 的身分進入。你可以編輯她的草稿，也可以查看課程團隊已選用的教材；你沒有編輯核可權，不能更改講義選文清單或出版社的頁面模板。\\n\\n範圍外：本練習之外的 Kestrel Press 發布系統、其他投稿者的帳號，以及阻斷服務。\\n\\n## 交戰規則\\n\\n這是針對 Kestrel Press 控制系統的授權練習。取得需要說明問題的證據後便停止；不要更改選文清單，也不要破壞教材內容。\\n\\nKestrel Press 已公開本次評估所需的應用程式原始碼與頁面模板。請把它們和正在運作的編輯台一起閱讀。\\n\\n## 委託目標\\n\\nKestrel Press 聲稱，只有課程編輯選用的內容才會影響講義預覽，而且投稿者撰寫的內容在整個過程中都只是一般稿件文字。\\n\\n驗證這個承諾。確認投稿者是否能影響已選用的節錄，以及 Kestrel Press 組裝講義時，這個影響是否仍只是文字。Kestrel Press 接受的證據是 `/flag.txt` 的內容；正常頁面與原始碼檔案都不會提供它。\\n\\n## 交付項目\\n\\n`/flag.txt` 的內容、產生它的請求，以及到達它所需兩個獨立缺陷的說明。\\n"},"headers":[],"relativePath":"zh-TW/challenge/selected-excerpts/index.md","filePath":"zh-TW/challenge/selected-excerpts/index.md"}'),l={name:"zh-TW/challenge/selected-excerpts/index.md"};function n(o,e,c,i,p,d){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="精選節錄" tabindex="-1">精選節錄 <a class="header-anchor" href="#精選節錄" aria-label="Permalink to “精選節錄”">​</a></h1><p><strong>客戶：</strong> 獨立教育出版社 Kestrel Press。 <strong>委託：</strong> 對投稿者編輯台，以及由已選用節錄組成的講義預覽進行白箱評估。</p><h2 id="測試範圍" tabindex="-1">測試範圍 <a class="header-anchor" href="#測試範圍" aria-label="Permalink to “測試範圍”">​</a></h2><p>範圍內：此來源所提供的教材選文編輯台、它公開的每一個 HTTP 端點，以及隨應用程式掛載的原始碼檔案。</p><p>你以一般投稿者 <strong>Leah Navarro</strong> 的身分進入。你可以編輯她的草稿，也可以查看課程團隊已選用的教材；你沒有編輯核可權，不能更改講義選文清單或出版社的頁面模板。</p><p>範圍外：本練習之外的 Kestrel Press 發布系統、其他投稿者的帳號，以及阻斷服務。</p><h2 id="交戰規則" tabindex="-1">交戰規則 <a class="header-anchor" href="#交戰規則" aria-label="Permalink to “交戰規則”">​</a></h2><p>這是針對 Kestrel Press 控制系統的授權練習。取得需要說明問題的證據後便停止；不要更改選文清單，也不要破壞教材內容。</p><p>Kestrel Press 已公開本次評估所需的應用程式原始碼與頁面模板。請把它們和正在運作的編輯台一起閱讀。</p><h2 id="委託目標" tabindex="-1">委託目標 <a class="header-anchor" href="#委託目標" aria-label="Permalink to “委託目標”">​</a></h2><p>Kestrel Press 聲稱，只有課程編輯選用的內容才會影響講義預覽，而且投稿者撰寫的內容在整個過程中都只是一般稿件文字。</p><p>驗證這個承諾。確認投稿者是否能影響已選用的節錄，以及 Kestrel Press 組裝講義時，這個影響是否仍只是文字。Kestrel Press 接受的證據是 <code>/flag.txt</code> 的內容；正常頁面與原始碼檔案都不會提供它。</p><h2 id="交付項目" tabindex="-1">交付項目 <a class="header-anchor" href="#交付項目" aria-label="Permalink to “交付項目”">​</a></h2><p><code>/flag.txt</code> 的內容、產生它的請求，以及到達它所需兩個獨立缺陷的說明。</p>',14)])])}const P=s(l,[["render",n]]);export{m as __pageData,P as default};
